-- Test bots bot1…bot8@bot.hamrah.invalid with profiles and outing profiles. TEST DATABASE ONLY (hamrah-dev).
-- Run in the Supabase SQL editor of the test project, with the password you keep in .env.local as BOT_PASSWORD:
--   set hamrah.bot_password = '...';   -- then run the rest of this file in the same session
-- Bots log in with that password; scripts/bots.mjs and e2e/bots.spec.ts use them.
do $$ declare b jsonb; uid uuid; em text; pw text := current_setting('hamrah.bot_password'); begin
for b in select * from jsonb_array_elements('[{"k": "bot1", "n": "آیدا", "av": "🌻", "city": "روتردام", "bio": "طراح محصول؛ آخر هفته‌ها کافه و نمایشگاه.", "hob": ["کتاب", "عکاسی", "نقاشی و هنر"], "act": ["قهوه", "موزه و گالری", "صبحانه/برانچ"], "g": "woman", "by": 1994, "job": "طراح محصول", "lat": 51.92, "lng": 4.48, "alc": "sometimes", "alcs": "mutual"}, {"k": "bot2", "n": "نیلوفر", "av": "🎧", "city": "روتردام", "bio": "دانشجوی ارشد؛ دنبال همراه برای درس و پیاده‌روی.", "hob": ["موسیقی", "زبان‌آموزی", "یوگا"], "act": ["پیاده‌روی", "قهوه", "کتاب‌فروشی و کتابخانه"], "g": "woman", "by": 1998, "job": "دانشجو", "lat": 51.91, "lng": 4.47, "alc": "no", "alcs": "hidden"}, {"k": "bot3", "n": "ترانه", "av": "🎨", "city": "دلفت", "bio": "نقاش؛ عاشق بازارچه‌ها و کارگاه.", "hob": ["نقاشی و هنر", "مد و لباس", "گیاه و باغبانی"], "act": ["کلاس و کارگاه", "خرید و بازارچه", "شام"], "g": "woman", "by": 1991, "job": "نقاش", "lat": 52.01, "lng": 4.36, "alc": "no", "alcs": "hidden"}, {"k": "bot4", "n": "شیما", "av": "🏸", "city": "لاهه", "bio": "مهندس نرم‌افزار؛ بدمینتون و بردگیم.", "hob": ["ورزش", "بردگیم", "تکنولوژی"], "act": ["ورزش", "بردگیم", "شام"], "g": "woman", "by": 1990, "job": "مهندس نرم‌افزار", "lat": 52.07, "lng": 4.3, "alc": "sometimes", "alcs": "mutual"}, {"k": "bot5", "n": "پریسا", "av": "📚", "city": "روتردام", "bio": "معلم زبان؛ کتاب‌خوان، اهل شعر.", "hob": ["کتاب", "شعر", "فلسفه"], "act": ["کتاب‌فروشی و کتابخانه", "قهوه", "سینما"], "g": "woman", "by": 1987, "job": "معلم", "lat": 51.93, "lng": 4.49, "alc": "no", "alcs": "hidden"}, {"k": "bot6", "n": "کاوه", "av": "🚲", "city": "آمستردام", "bio": "دوچرخه‌سوار و عکاس آماتور.", "hob": ["سفر", "عکاسی", "طبیعت‌گردی"], "act": ["دوچرخه‌سواری", "سفر یک‌روزه", "پیاده‌روی"], "g": "man", "by": 1992, "job": "تحلیلگر داده", "lat": 52.37, "lng": 4.9, "alc": "no", "alcs": "hidden"}, {"k": "bot7", "n": "سپیده", "av": "💃", "city": "روتردام", "bio": "دنبال جمع برای رقص و کارائوکه.", "hob": ["رقص", "موسیقی", "تئاتر"], "act": ["رقص", "کارائوکه", "کنسرت و موسیقی زنده"], "g": "woman", "by": 1996, "job": "پرستار", "lat": 51.92, "lng": 4.46, "alc": "sometimes", "alcs": "hidden"}, {"k": "bot8", "n": "مهسا", "av": "🧺", "city": "اوترخت", "bio": "پیک‌نیک، فیلم و آشپزی.", "hob": ["آشپزی", "فیلم و سریال", "حیوانات"], "act": ["پارک و پیک‌نیک", "سینما", "شام"], "g": "woman", "by": 1993, "job": "حسابدار", "lat": 52.09, "lng": 5.12, "alc": "no", "alcs": "hidden"}]'::jsonb) loop
 em := (b->>'k')||'@bot.hamrah.invalid';
 select id into uid from auth.users where email=em;
 if uid is null then uid:=gen_random_uuid();
  insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,recovery_token,email_change_token_new,email_change)
  values('00000000-0000-0000-0000-000000000000',uid,'authenticated','authenticated',em,extensions.crypt(pw,extensions.gen_salt('bf')),now(),'{"provider":"email","providers":["email"]}','{"bot":true}',now(),now(),'','','','');
  insert into auth.identities(id,user_id,provider_id,identity_data,provider,last_sign_in_at,created_at,updated_at) values(gen_random_uuid(),uid,uid::text,jsonb_build_object('sub',uid::text,'email',em,'email_verified',true),'email',now(),now(),now());
 else update auth.users set encrypted_password=extensions.crypt(pw,extensions.gen_salt('bf')) where id=uid; end if;
 insert into public.profiles(id,name,avatar,city,bio,interests,teach_langs,learn_langs,mode,verified_email)
  values(uid,(b->>'n')||' (بات)',b->>'av',b->>'city',b->>'bio',array(select jsonb_array_elements_text(b->'hob')),array['فارسی'],array['هلندی'],'both',true)
  on conflict(id) do update set name=excluded.name,avatar=excluded.avatar,city=excluded.city,bio=excluded.bio,interests=excluded.interests;
 insert into public.outing_profiles(user_id,birth_year,gender,job,hobbies,activities,places_liked,languages,budget,area_label,area_lat,area_lng,radius_km,free_slots,vis,pref,builder_step)
  values(uid,(b->>'by')::int,b->>'g',b->>'job',array(select jsonb_array_elements_text(b->'hob')),array(select jsonb_array_elements_text(b->'act')),'{}','{فارسی,هلندی}','mid',b->>'city',(b->>'lat')::numeric,(b->>'lng')::numeric,40,'{fri:evening,sat:afternoon,sat:evening,sun:morning,wed:evening}','{"age":"public","job":"public","hobbies":"public","places":"matched"}','{}',99)
  on conflict(user_id) do update set activities=excluded.activities,hobbies=excluded.hobbies,free_slots=excluded.free_slots,area_lat=excluded.area_lat,area_lng=excluded.area_lng,radius_km=excluded.radius_km,builder_step=99;
 insert into public.outing_lifestyle(user_id,alcohol,cannabis,smoking,alcohol_share) values(uid,b->>'alc','no','no',b->>'alcs') on conflict(user_id) do nothing;
end loop; end $$;
select email from auth.users where email like '%@bot.hamrah.invalid' order by email;
